from pathlib import Path
import json,sys,torch
ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT/'experiments'))
from y_host_calibration_io_v1 import unpack as unpack_host
torch.set_num_threads(6);torch.set_grad_enabled(False)
host=torch.load(ROOT/'host/ckpt.pt',weights_only=True,mmap=True)['model'];delta=torch.load(ROOT/'experiments/z8_complete_g4/delta.pt',weights_only=True);native678,_=unpack_host(torch.load(ROOT/'artifacts/y_host_native678_bad4_v1.pt',weights_only=True,mmap=True));native5=torch.load(ROOT/'artifacts/o_host_calib25.pt',weights_only=True,mmap=True);native11=torch.load(ROOT/'artifacts/o_host_calib11.pt',weights_only=True,mmap=True);sources={5:'z2b_native_capacity',6:'z3b_saturated_columns',7:'z5_carry_markers',8:'z7c_sharp_later_phases',11:'z8_complete_g4'};donor_counts={5:512,6:768,7:512,8:512,11:752};changed={};repairs={};reports=[]
for layer in (5,6,7,8,11):
 aux=torch.load(ROOT/'experiments'/sources[layer]/'circuit.pt',weights_only=True);selected=aux['repair']['selected'];data=native5 if layer==5 else native11 if layer==11 else native678;acts=data['captures'][f'{layer}.gelu'].reshape(-1,3072).double();n=(384 if layer in (5,11) else 256)*64;A=acts[:n];mu=A.mean(0);cov=A.T@A/n-mu[:,None]*mu[None];W=host[f'transformer.h.{layer}.mlp.c_proj.weight'].double();Ps=W[:,selected];cross=cov[:,selected];G=Ps.T@Ps;score=(cross*(cross@G)).sum(1).clamp_min(0)/cov.diagonal().clamp_min(1e-8);score[selected]=-1;donors=score.argsort(descending=True)[:donor_counts[layer]];C=cov[donors][:,donors];post=data['captures'][f'{layer}.raw'].reshape(-1,768).double()+acts@W.T+host[f'transformer.h.{layer}.mlp.c_proj.bias'].double();sigma=(post.var(1,unbiased=False,keepdim=True)+1e-5).sqrt();target=acts[:,selected];trials=[];best=None
 for ridge in (.001,.0001,1e-5,1e-6,1e-7):
  regular=C.clone();regular.diagonal().add_(ridge*C.diagonal().clamp_min(1e-8));R=torch.linalg.solve(regular,cross[donors]);offset=mu[selected]-mu[donors]@R;residual=(target-acts[:,donors]@R-offset)@Ps.T;report={'layer':layer,'native_donors':donor_counts[layer],'ridge':ridge,'lost_feature_count':len(selected),'construction_local_raw_rms':float(residual[:n].square().mean().sqrt()),'validation_local_raw_rms':float(residual[n:].square().mean().sqrt()),'validation_local_normalized_rms':float((residual[n:]/sigma[n:]).square().mean().sqrt()),'displaced_validation_raw_rms':float((target[n:]@Ps.T).square().mean().sqrt())};trials.append(report);print('capacity',json.dumps(report),flush=True)
  if best is None or report['validation_local_normalized_rms']<best['report']['validation_local_normalized_rms']:best={'reconstruction':R,'offset':offset,'report':report}
 key=f'transformer.h.{layer}.mlp.c_proj.weight';oldP=host[key].clone();u=delta['updates'][key];oldP.view(-1)[u['indices'].long()]=u['values'];P=W.clone();P[:,donors]+=Ps@best['reconstruction'].T;P[:,selected]=oldP[:,selected].double();bias=host[f'transformer.h.{layer}.mlp.c_proj.bias'].double()+Ps@best['offset'];changed[key]=P.float();changed[f'transformer.h.{layer}.mlp.c_proj.bias']=bias.float();repairs[layer]={'selected':selected,'donors':donors,**best,'trials':trials};reports.append(best['report'])
# The valid equals query dominates LN5, so the native MLP5 output is nearly
