aux5=torch.load(ROOT/'experiments/z2b_native_capacity/circuit.pt',weights_only=True);eq=torch.load(ROOT/'artifacts/z_reader_attention_v2_eq.pt',weights_only=True);x=eq['ln2'][:384];sel=repairs[5]['selected'];gelu=torch.nn.functional.gelu(torch.nn.functional.linear(x,host['transformer.h.5.mlp.c_fc.weight'],host['transformer.h.5.mlp.c_fc.bias']));gelu[:,sel]=0;key='transformer.h.5.mlp.c_proj.weight';oldP=host[key].clone();u=delta['updates'][key];oldP.view(-1)[u['indices'].long()]=u['values'];keyb='transformer.h.5.mlp.c_proj.bias';oldb=host[keyb].clone();u=delta['updates'][keyb];oldb.view(-1)[u['indices'].long()]=u['values'];difference=torch.nn.functional.linear(gelu,oldP-changed[key],oldb-changed[keyb]).double();mean=difference[:192].mean(0);changed[key][:,sel[-2]]+=(mean/4).float();changed[key][:,sel[-1]]-=(mean/4).float();eqreport={'construction_equals_count':192,'validation_equals_count':192,'mean_correction_norm':float(mean.norm()),'validation_residual_rms':float((difference[192:]-mean).square().mean().sqrt()),'validation_residual_max':float((difference[192:]-mean).abs().max()),'reader_memory_residual_max':float(((difference-mean)@aux5['retained_operand_memory']).abs().max()),'caveat':'Recorded equals inputs predate the small native4 donor reallocation; this is a local conditional mean compensation, not a full-model verification.'};print('equals compensation',json.dumps(eqreport),flush=True)
maximum=max(float(x.abs().max()) for x in changed.values());assert maximum<=1e6;torch.save({'changed':changed,'repairs':repairs,'chosen_reports':reports,'donor_counts':donor_counts,'equals_compensation':mean,'equals_report':eqreport,'maximum_new_weight':maximum,'target_definition':__doc__},ROOT/'artifacts/za_local_capacity_v1.pt');(ROOT/'artifacts/za_local_capacity_v1.json').write_text(json.dumps({'chosen_reports':reports,'all_trials':{str(k):v['trials'] for k,v in repairs.items()},'equals_report':eqreport,'maximum_new_weight':maximum},indent=2)+'\n')
